mapper.select:
select

con.Con_Name as conName,
con.Con_Party_B_Id as conPartyBId,
con2.Con_Name as eaPurchaseContractName,
c1.C_Name_History as eaSupervisorNameHistory,
c2.C_Name_History as eaDesignNameHistory,
c3.C_Name_History as conPartyBNameHistory,
c1.C_Name as eaSupervisorName,
c2.C_Name as eaDesignName,
c3.C_Name as conPartyBName,
c1.C_Abbreviation as eaSupervisorAbbName,
c2.C_Abbreviation as eaDesignAbbName,
c3.C_Abbreviation as conPartyBAbbName,
f.file_relation_id as fileRelationId,
mn.*
from Me_Enter_Apply mn
left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Con_Contract con2 on con2.Con_Id=mn.Ea_Purchase_Contract

left join SYS_Company c1 on mn.Ea_Supervisor_Id=c1.C_Id
left join SYS_Company c2 on mn.Ea_Design_Id=c2.C_Id
left join Sys_File f on f.FileID=mn.Ea_Id
left join SYS_Company c3 on con.Con_Party_B_Id=c3.C_Id
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and con.Con_Party_B_Id = #{params.conPartyBId}


    and mn.Ea_Witness = #{params.eaWitness}


    and mn.Ea_Project_Team = #{params.eaProjectTeam}


    and mn.Ea_Supervisor_Id = #{params.eaSupervisorId}


    and mn.Ea_Design_Id = #{params.eaDesignId}


    and mn.P_Id = #{params.pId}


    and mn.Con_Id = #{params.conId}


    and mn.Ea_Purchase_Contract = #{params.eaPurchaseContract}


    and mn.Ea_Code like concat('%',#{params.eaCode},'%')


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    and con.Con_Name like concat('%',#{params.conName},'%')


    and con2.Con_Name like concat('%',#{params.eaPurchaseContractName},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Ea_Create_Time desc
